#!/usr/bin/env node
/**
 * Git pre-commit, generated by the kura-hooks-setup skill, `.githooks/pre-commit` only starts this file.
 * Code staged: CONFIG.checkCommand must be green, or there is no commit. Only notes staged: nothing runs.
 * shortcut: checks the working tree, not the staged index, stash unstaged changes first when they differ.
 */
import { spawnSync } from 'node:child_process';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

// ---- CONFIG: filled in per repo by kura-hooks-setup ----
const CONFIG = {
    checkCommand: ['npm', 'run', 'check'],  // e.g. ['dotnet', 'build', '--no-restore'] or ['pytest', '-q']
    notes: /^(?:docs|backlog)\/|\.md$/i     // staged paths that need no checks
};
// ---- end CONFIG ----

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const needsChecks = (staged) => staged.some(file => !CONFIG.notes.test(file));

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
    const staged = spawnSync('git', ['diff', '--cached', '--name-only', '--diff-filter=ACMRD'], { cwd: ROOT, windowsHide: true, encoding: 'utf8' }).stdout.split(/\r?\n/).filter(Boolean);
    if (!needsChecks(staged)) process.exit(0);
    console.log(`pre-commit: ${CONFIG.checkCommand.join(' ')}`);
    const [cmd, ...args] = CONFIG.checkCommand;
    const check = spawnSync(cmd, args, { cwd: ROOT, windowsHide: true, stdio: 'inherit', shell: process.platform === 'win32' });
    if (check.status !== 0) { console.log('pre-commit: check is red, no commit'); process.exit(1); }
}
